// HDP/1 control messages (spec §4.4, §4.5). Source of truth for
// schemas/hdp.v1.schema.json (generated by `pnpm gen:schema`).
// Objects allow additional properties: unknown fields must be ignored (§4.8).
import { Type, type Static, type TLiteral, type TSchema, type TUnion } from "@sinclair/typebox";

export const HDP_VERSION = 1;
export const HDP_SUBPROTOCOL = "hdp.v1";

const Str = (opts = {}) => Type.String(opts);
const Uint = (opts = {}) => Type.Integer({ minimum: 0, ...opts });
const msg = <T extends string, P extends Record<string, TSchema>>(type: T, props: P, description: string) =>
  Type.Object({ type: Type.Literal(type), ...props }, { description });
const Enum = <const T extends readonly string[]>(values: T, opts = {}) =>
  Type.Union(
    values.map((v) => Type.Literal(v)),
    opts,
  ) as unknown as TUnion<{ -readonly [K in keyof T]: TLiteral<T[K]> }>;

// ---------------------------------------------------------------------------
// Shared

export const AudioStreamParams = Type.Object(
  {
    format: Type.Union([Type.Literal("opus"), Type.Literal("pcm16")]),
    sample_rate: Uint(),
    channels: Uint({ minimum: 1 }),
    frame_ms: Uint({ minimum: 1 }),
  },
);

export const ToolDescriptor = Type.Object(
  {
    name: Str({ minLength: 1 }),
    description: Str(),
    inputSchema: Type.Object({}, { description: "JSON Schema of the tool arguments" }),
  },
);

const JsonRpcId = Type.Union([Type.String(), Type.Integer()]);

export const JsonRpcRequest = Type.Object(
  {
    jsonrpc: Type.Literal("2.0"),
    id: JsonRpcId,
    method: Str(),
    params: Type.Optional(Type.Unknown()),
  },
);

export const JsonRpcResponse = Type.Object(
  {
    jsonrpc: Type.Literal("2.0"),
    id: JsonRpcId,
    result: Type.Optional(Type.Unknown()),
    error: Type.Optional(
      Type.Object({ code: Type.Integer(), message: Str(), data: Type.Optional(Type.Unknown()) }),
    ),
  },
);

export const AvatarState = Enum(["idle", "listening", "thinking", "working", "speaking", "confirming", "sleeping", "offline", "error"]);

export const ListenTrigger = Enum(["wake_word", "touch", "button", "motion", "follow_up"]);

export const SessionConfig = Type.Object(
  {
    follow_up_window_ms: Type.Optional(Uint()),
    captions: Type.Optional(Type.Boolean()),
    language: Type.Optional(Str()),
  },
);

// ---------------------------------------------------------------------------
// Device → server

export const DeviceHello = msg(
  "hello",
  {
    version: Uint({ minimum: 1 }),
    device: Type.Object({
      model: Str({ minLength: 1 }),
      firmware: Str(),
      board: Type.Optional(Str()),
    }),
    capabilities: Type.Object({
      display: Type.Optional(
        Type.Object({
          width: Uint(),
          height: Uint(),
          shape: Type.Union([Type.Literal("round"), Type.Literal("rect")]),
          color_depth: Type.Optional(Uint()),
        }),
      ),
      audio: Type.Object({
        input: AudioStreamParams,
        output: Type.Object({
          formats: Type.Array(Str(), { minItems: 1 }),
          sample_rates: Type.Array(Uint(), { minItems: 1 }),
        }),
        mics: Type.Optional(Uint()),
        aec: Type.Optional(Type.Boolean()),
        wake_word: Type.Optional(Type.Boolean()),
      }),
      input: Type.Optional(Type.Array(Str())),
      power: Type.Optional(Type.Object({ battery: Type.Boolean() })),
      avatar: Type.Optional(Type.Object({ engine: Str(), emotes: Type.Array(Str()) })),
    }),
    tools: Type.Optional(Type.Array(ToolDescriptor)),
    resume: Type.Optional(Type.Object({ session_id: Str() })),
  },
  "Device capability descriptor; first message on a connection",
);

export const DeviceListen = msg(
  "listen",
  {
    state: Type.Union([Type.Literal("start"), Type.Literal("stop")]),
    mode: Type.Optional(Type.Union([Type.Literal("auto"), Type.Literal("manual"), Type.Literal("realtime")])),
    trigger: Type.Optional(ListenTrigger),
    wake_word: Type.Optional(Str()),
  },
  "Begin/end an utterance; auto = server endpointing, manual = push-to-talk",
);

export const Abort = msg(
  "abort",
  { reason: Type.Union([Type.Literal("barge_in"), Type.Literal("user_cancel"), Type.Literal("wake_word")]) },
  "Interrupt current turn / playback",
);

export const TtsPlayed = msg("tts.played", { segment_id: Uint() }, "Segment fully played");

export const ToolResult = msg("tool.result", { payload: JsonRpcResponse }, "Result of a device tool call");

export const ConfirmResult = msg(
  "confirm.result",
  { request_id: Str(), approved: Type.Boolean() },
  "User answer to a confirmation request",
);

export const DeviceEvent = msg(
  "event",
  { name: Str({ minLength: 1 }), data: Type.Optional(Type.Unknown()) },
  "Asynchronous device event",
);

export const Goodbye = msg("goodbye", { reason: Str() }, "Graceful disconnect");

export const DeviceMessages = [
  DeviceHello,
  DeviceListen,
  Abort,
  TtsPlayed,
  ToolResult,
  ConfirmResult,
  DeviceEvent,
  Goodbye,
] as const;

// ---------------------------------------------------------------------------
// Server → device

export const ServerHello = msg(
  "hello",
  {
    session_id: Str({ minLength: 1 }),
    audio: Type.Object({ output: AudioStreamParams }),
    config: SessionConfig,
  },
  "Session established; downlink audio params and config",
);

export const ServerListen = msg(
  "listen",
  { state: Type.Literal("stop") },
  "Server-side endpoint detected; device stops uplink",
);

export const Stt = msg("stt", { text: Str(), final: Type.Boolean() }, "User transcript (captions)");

export const AgentStatus = msg(
  "agent.status",
  {
    phase: Enum(["thinking", "tool", "responding", "done", "error"]),
    tool: Type.Optional(Str()),
    detail: Type.Optional(Str()),
  },
  "Agent progress",
);

export const Tts = msg(
  "tts",
  {
    state: Enum(["start", "segment_start", "segment_end", "stop"]),
    segment_id: Type.Optional(Uint()),
    text: Type.Optional(Str()),
  },
  "Speech output framing; text for captions",
);

export const Avatar = msg(
  "avatar",
  {
    state: Type.Optional(AvatarState),
    emote: Type.Optional(Str()),
    intensity: Type.Optional(Type.Number({ minimum: 0, maximum: 1 })),
    duration_ms: Type.Optional(Uint()),
    gaze: Type.Optional(
      Type.Object({ x: Type.Number({ minimum: -1, maximum: 1 }), y: Type.Number({ minimum: -1, maximum: 1 }) }),
    ),
  },
  "Avatar control (spec 06)",
);

export const ToolCall = msg("tool.call", { payload: JsonRpcRequest }, "Invoke a device tool (method tools/call)");

export const ConfirmRequest = msg(
  "confirm.request",
  { request_id: Str(), title: Str(), detail: Str(), timeout_ms: Uint() },
  "Ask user to approve a risky agent action",
);

export const Notify = msg(
  "notify",
  { text: Str(), level: Type.Union([Type.Literal("info"), Type.Literal("warning"), Type.Literal("alert")]) },
  "Proactive notification",
);

export const Config = msg("config", { config: SessionConfig }, "Runtime config update (partial)");

export const ErrorCode = Enum(["unsupported_version", "unauthorized", "hello_required", "bad_message", "busy", "internal"]);

export const ErrorMessage = msg("error", { code: ErrorCode, message: Str() }, "Protocol / server error");

export const ServerMessages = [
  ServerHello,
  ServerListen,
  Stt,
  AgentStatus,
  Tts,
  Avatar,
  ToolCall,
  ConfirmRequest,
  Notify,
  Config,
  ErrorMessage,
] as const;

// ---------------------------------------------------------------------------
// Static types

export type DeviceHello = Static<typeof DeviceHello>;
export type DeviceListen = Static<typeof DeviceListen>;
export type Abort = Static<typeof Abort>;
export type TtsPlayed = Static<typeof TtsPlayed>;
export type ToolResult = Static<typeof ToolResult>;
export type ConfirmResult = Static<typeof ConfirmResult>;
export type DeviceEvent = Static<typeof DeviceEvent>;
export type Goodbye = Static<typeof Goodbye>;
export type DeviceMessage = Static<(typeof DeviceMessages)[number]>;

export type ServerHello = Static<typeof ServerHello>;
export type ServerListen = Static<typeof ServerListen>;
export type Stt = Static<typeof Stt>;
export type AgentStatus = Static<typeof AgentStatus>;
export type Tts = Static<typeof Tts>;
export type Avatar = Static<typeof Avatar>;
export type ToolCall = Static<typeof ToolCall>;
export type ConfirmRequest = Static<typeof ConfirmRequest>;
export type Notify = Static<typeof Notify>;
export type Config = Static<typeof Config>;
export type ErrorMessage = Static<typeof ErrorMessage>;
export type ErrorCode = Static<typeof ErrorCode>;
export type ServerMessage = Static<(typeof ServerMessages)[number]>;

export type AudioStreamParams = Static<typeof AudioStreamParams>;
export type ToolDescriptor = Static<typeof ToolDescriptor>;
export type JsonRpcRequest = Static<typeof JsonRpcRequest>;
export type JsonRpcResponse = Static<typeof JsonRpcResponse>;
export type AvatarState = Static<typeof AvatarState>;
export type SessionConfig = Static<typeof SessionConfig>;
